const payload = $input.first().json.body ?? {};
const pedido = payload.data ?? {};
const cliente = pedido.customer ?? {};
const items = Array.isArray(pedido.items) ? pedido.items : [];
const errores = [];

// Funciones auxiliares
const idValido = (id) => Number.isInteger(id) && id > 0;

const importe = (valor) => {
  if (typeof valor !== 'string' ||
      !/^\d+(\.\d{1,2})?$/.test(valor.trim())) {
    return null;
  }
  return Number(valor);
};

// 1. Validar el contrato JSON v1.0
if (payload.schema_version !== '1.0') {
  errores.push('schema_version incorrecta');
}

if (!idValido(payload.event_id)) {
  errores.push('event_id no válido');
}

if (payload.event_type !== 'order.created') {
  errores.push('event_type no válido');
}

if (!payload.occurred_at ||
    Number.isNaN(Date.parse(payload.occurred_at))) {
  errores.push('Fecha no válida');
}

if (!idValido(payload.order_id)) {
  errores.push('order_id no válido');
}

// 2. Validar los datos del pedido
if (!pedido.status) {
  errores.push('Falta estado del pedido');
}

if (typeof pedido.currency !== 'string' ||
    !/^[A-Z]{3}$/.test(pedido.currency)) {
  errores.push('Moneda no válida');
}

const total = importe(pedido.total);
if (total === null) {
  errores.push('Importe total no válido');
}

// 3. Validar el cliente (admite invitados)
if (cliente.id !== null && !idValido(cliente.id)) {
  errores.push('ID de cliente no válido');
}

if (typeof cliente.name !== 'string' ||
    !cliente.name.trim()) {
  errores.push('Falta nombre del cliente');
}

if (typeof cliente.email !== 'string' ||
    !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cliente.email)) {
  errores.push('Email de cliente no válido');
}

// 4. Validar los productos (SKU puede estar vacío)
if (items.length === 0) {
  errores.push('Pedido sin productos');
}

for (const item of items) {
  if (!idValido(item?.product_id)) {
    errores.push('product_id no válido');
  }

  if (typeof item?.sku !== 'string') {
    errores.push('SKU no válido');
  }

  if (typeof item?.name !== 'string' || !item.name.trim()) {
    errores.push('Nombre de producto no válido');
  }

  if (!idValido(item?.quantity)) {
    errores.push('Cantidad no válida');
  }

  if (importe(item?.total) === null) {
    errores.push('Total de línea no válido');
  }
}

// 5. Preparar los campos para Google Sheets
const items_summary = items
  .map(item => `${item?.name ?? 'Producto'} x${item?.quantity ?? 0}`)
  .join(', ');

return [{
  json: {
    valid: errores.length === 0,
    errors: errores,
    schema_version: payload.schema_version ?? null,
    event_id: payload.event_id ?? null,
    event_type: payload.event_type ?? null,
    occurred_at: payload.occurred_at ?? null,
    order_id: payload.order_id ?? null,
    order_number: pedido.order_number ?? null,
    status: pedido.status ?? null,
    currency: pedido.currency ?? null,
    total: total,
    customer_id: cliente.id ?? null,
    customer_name: cliente.name ?? null,
    customer_email: cliente.email ?? null,
    payment_method: pedido.payment_method ?? null,
    items_summary: items_summary,
    items: items.map(item => ({
      product_id: item?.product_id ?? null,
      sku: item?.sku ?? '',
      name: item?.name ?? null,
      quantity: item?.quantity ?? null,
      total: importe(item?.total)
    }))
  }
}];
